{"cards": [{"node_code": "N_8fb477a53609ab14", "definition": "研究道路沿线地表及内部排水系统的设计与布置，旨在排除路面水、路基水及边坡水，保障道路结构稳定与行车安全。", "boundary": "本节点聚焦于服务于道路线形与路基稳定性的排水工程。包括边沟、截水沟、排水沟、涵洞及路面渗水层等。边界在于区分“道路专用排水”与“市政综合排水”，城市雨水管网归入市政节点。不包含纯水文理论或大型水利枢纽工程。", "includes": ["道路地表排水设施（边沟、截水沟、急流槽等）的设计与布置", "路基内部排水（渗沟、盲沟、排水板等）及路面排水构造", "涵洞、排水桥等过水构造物的选型与布置"], "excludes": ["城市雨水管网、污水处理厂等市政水务设施", "大型河流治理、水库大坝等水利枢纽工程"], "sibling_distinctions": [{"other_code": "N_6263567abec3e136", "rule": "本节点关注水的排除与疏导，兄弟节点关注路基土体的结构组成、压实及强度。"}, {"other_code": "N_30984d17d6333486", "rule": "本节点通过排水防止水害，兄弟节点通过工程措施（如挡墙、护坡）防止土体失稳，二者常配合使用但功能不同。"}], "cross_boundary_rule": "当排水设施与路基结构紧密耦合（如路基内部渗沟），归入本节点；若涉及大型水利设施或城市管网，则归入相应市政或水利节点。"}, {"node_code": "N_fc1db5b901301d9f", "definition": "研究在给定地形、地质及社会经济约束下，确定道路中心线空间位置的过程，包括选线原则、方案比选及定线方法。", "boundary": "本节点聚焦于路线走向的宏观决策与空间定位。包括初步选线、带状选线及详细定线。边界在于区分“选线决策”与“线形几何设计”，具体的平纵曲线参数计算归入线形节点。不包含纯城市规划或土地利用规划。", "includes": ["路线选线原则（如最短、最经济、最安全）及方案比选方法", "地形图上的路线布设、控制点确定及带状地形图应用", "路线与交叉工程、环境敏感区的协调处理策略"], "excludes": ["平面、纵断面、横断面的具体几何参数计算与设计", "路基、路面、桥梁等具体构造物的结构设计"], "sibling_distinctions": [{"other_code": "N_f9630db1fd8e2a2b", "rule": "本节点关注路线“在哪里”（空间位置与走向），兄弟节点关注路线“长什么样”（几何线形与参数）。"}, {"other_code": "N_6263567abec3e136", "rule": "本节点关注宏观路线布局，兄弟节点关注微观路基结构。"}], "cross_boundary_rule": "当选线方案直接影响线形几何参数时，选线方案归入本节点，线形具体设计归入线形节点。"}]}
